using System.Diagnostics;
using System.Drawing.Drawing2D;
using Microsoft.Win32;
using System.Windows.Forms;
internal static class Program { [STAThread] private static void Main(){ ApplicationConfiguration.Initialize(); Application.Run(new BridgeDashboard()); } }
internal sealed class BridgeDashboard : Form {
 readonly Color bg=Color.FromArgb(14,15,24), panel=Color.FromArgb(23,25,39), purple=Color.FromArgb(116,83,255), muted=Color.FromArgb(157,160,184);
 readonly Label state=new(), pin=new(), ips=new(), device=new(), uptime=new();
 readonly RichTextBox log=new(); readonly NotifyIcon tray=new(); readonly System.Windows.Forms.Timer clock=new(){Interval=1000};
 Process? service; DateTime started=DateTime.Now; bool closing;
 const string RunKey=@"Software\Microsoft\Windows\CurrentVersion\Run"; const string AppName="DECKRA Bridge";
 public BridgeDashboard(){ Text="DECKRA Bridge"; MinimumSize=new Size(760,560); Size=new Size(920,690); StartPosition=FormStartPosition.CenterScreen; BackColor=bg; ForeColor=Color.White; Font=new Font("Segoe UI",10); Icon=MakeIcon(); BuildUi(); tray.Icon=Icon; tray.Text="DECKRA Bridge"; tray.Visible=true; tray.DoubleClick+=(_,_)=>RestoreWindow(); var menu=new ContextMenuStrip(); menu.Items.Add("Abrir DECKRA Bridge",null,(_,_)=>RestoreWindow()); menu.Items.Add("Encerrar Bridge",null,(_,_)=>ExitApp()); tray.ContextMenuStrip=menu; Shown+=(_,_)=>StartService(); FormClosing+=ClosingHandler; clock.Tick+=(_,_)=>uptime.Text="Ativo há "+(DateTime.Now-started).ToString(@"hh\:mm\:ss"); clock.Start(); }
 Panel Card()=>new(){Dock=DockStyle.Fill,BackColor=panel,Padding=new Padding(16),Margin=new Padding(0,0,0,8)};
 void BuildUi(){ var root=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(24),ColumnCount=1,RowCount=5,BackColor=bg}; root.RowStyles.Add(new RowStyle(SizeType.Absolute,92)); root.RowStyles.Add(new RowStyle(SizeType.Absolute,112)); root.RowStyles.Add(new RowStyle(SizeType.Absolute,120)); root.RowStyles.Add(new RowStyle(SizeType.Percent,100)); root.RowStyles.Add(new RowStyle(SizeType.Absolute,42)); Controls.Add(root);
 var head=new Panel{Dock=DockStyle.Fill,BackColor=bg}; head.Controls.Add(new Label{Text="D",Font=new Font("Segoe UI",38,FontStyle.Bold),ForeColor=purple,AutoSize=true,Location=new Point(0,0)}); head.Controls.Add(new Label{Text="▯",Font=new Font("Segoe UI",17,FontStyle.Bold),ForeColor=Color.White,AutoSize=true,Location=new Point(31,39)}); head.Controls.Add(new Label{Text="D E C K R A",Font=new Font("Segoe UI",20,FontStyle.Bold),ForeColor=Color.White,AutoSize=true,Location=new Point(78,16)}); head.Controls.Add(new Label{Text="BRIDGE  •  WINDOWS",Font=new Font("Segoe UI",9),ForeColor=muted,AutoSize=true,Location=new Point(81,51)}); root.Controls.Add(head,0,0);
 var status=Card(); state.Text="●  Iniciando serviço..."; state.Font=new Font("Segoe UI Semibold",16); state.ForeColor=Color.Goldenrod; state.Location=new Point(18,15); state.AutoSize=true; uptime.Text="Ativo há 00:00:00"; uptime.ForeColor=muted; uptime.AutoSize=true; uptime.Location=new Point(20,57); status.Controls.Add(state); status.Controls.Add(uptime); root.Controls.Add(status,0,1);
 var info=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=3,RowCount=1,BackColor=bg,Padding=new Padding(0,10,0,10)}; for(int i=0;i<3;i++)info.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,33.333f)); info.Controls.Add(Info("PIN DE PAREAMENTO",pin),0,0); info.Controls.Add(Info("ENDEREÇOS DO PC",ips),1,0); info.Controls.Add(Info("DISPOSITIVO",device),2,0); root.Controls.Add(info,0,2);
 var logCard=Card(); log.Dock=DockStyle.Fill; log.ReadOnly=true; log.BorderStyle=BorderStyle.None; log.BackColor=panel; log.ForeColor=Color.FromArgb(205,208,228); log.Font=new Font("Consolas",9); logCard.Controls.Add(log); logCard.Controls.Add(new Label{Text="Atividade da Bridge",ForeColor=Color.White,Font=new Font("Segoe UI Semibold",12),Dock=DockStyle.Top,Height=34}); root.Controls.Add(logCard,0,3);
 var footer=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.RightToLeft,BackColor=bg}; var exit=new Button{Text="Encerrar",Width=110,Height=30,FlatStyle=FlatStyle.Flat,BackColor=panel,ForeColor=Color.White}; exit.Click+=(_,_)=>ExitApp(); var hide=new Button{Text="Minimizar para bandeja",Width=170,Height=30,FlatStyle=FlatStyle.Flat,BackColor=purple,ForeColor=Color.White}; hide.Click+=(_,_)=>HideToTray(); footer.Controls.Add(exit); footer.Controls.Add(hide); root.Controls.Add(footer,0,4);
 var startup=new CheckBox{Text="Iniciar com o Windows",AutoSize=true,ForeColor=muted,BackColor=bg,Left=28,Top=ClientSize.Height-38,Anchor=AnchorStyles.Left|AnchorStyles.Bottom,Checked=StartupOn()}; startup.CheckedChanged+=(_,_)=>SetStartup(startup.Checked); Controls.Add(startup); }
 Panel Info(string title,Label value){var c=Card(); c.Margin=new Padding(0,0,10,0); c.Controls.Add(new Label{Text=title,ForeColor=muted,Font=new Font("Segoe UI",8,FontStyle.Bold),AutoSize=true,Location=new Point(13,12)}); value.Text="Aguardando"; value.ForeColor=Color.White; value.Font=new Font("Segoe UI Semibold",11); value.AutoSize=false; value.Location=new Point(13,40); value.Size=new Size(220,55); c.Controls.Add(value); return c;}
 void StartService(){try{var path=Path.Combine(AppContext.BaseDirectory,"DeckraBridge.Service.exe"); if(!File.Exists(path)){SetState("●  Serviço não encontrado",Color.OrangeRed); Append("DeckraBridge.Service.exe deve ficar na mesma pasta."); return;} var si=new ProcessStartInfo(path){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,WorkingDirectory=AppContext.BaseDirectory}; service=new Process{StartInfo=si,EnableRaisingEvents=true}; service.OutputDataReceived+=(_,e)=>{if(e.Data!=null)BeginInvoke(new Action(()=>HandleLine(e.Data)));}; service.ErrorDataReceived+=(_,e)=>{if(e.Data!=null)BeginInvoke(new Action(()=>Append("ERRO: "+e.Data)));}; service.Exited+=(_,_)=>{if(!IsDisposed)BeginInvoke(new Action(()=>SetState("●  Serviço parado",Color.OrangeRed)));}; service.Start(); service.BeginOutputReadLine(); service.BeginErrorReadLine(); started=DateTime.Now; SetState("●  Bridge ativa • aguardando celular",Color.FromArgb(75,205,145)); Append("Aplicativo DECKRA Bridge iniciado.");}catch(Exception ex){SetState("●  Falha ao iniciar serviço",Color.OrangeRed);Append(ex.Message);}}
 void HandleLine(string line){Append(line); if(line.StartsWith("PIN de pareamento:"))pin.Text=line[(line.IndexOf(':')+1)..].Trim(); if(line.StartsWith("IP do PC"))ips.Text=string.Join(Environment.NewLine,(ips.Text+Environment.NewLine+line[(line.IndexOf(':')+1)..].Trim()).Split(Environment.NewLine).Where(x=>!string.IsNullOrWhiteSpace(x)).Distinct()); if(line.StartsWith("CELULAR_CONECTADO|")){device.Text=line.Split('|').Last();SetState("●  Celular conectado",Color.FromArgb(75,205,145));} if(line=="CELULAR_DESCONECTADO"){device.Text="Desconectado";SetState("●  Bridge ativa • aguardando celular",Color.Goldenrod);} if(line.StartsWith("Bridge pronta"))SetState("●  Bridge ativa • aguardando celular",Color.FromArgb(75,205,145));}
 void Append(string s)=>log.AppendText($"[{DateTime.Now:HH:mm:ss}] {s}{Environment.NewLine}"); void SetState(string s,Color c){state.Text=s;state.ForeColor=c;} void HideToTray(){Hide();tray.ShowBalloonTip(1800,"DECKRA Bridge","A Bridge continua ativa na bandeja do sistema.",ToolTipIcon.Info);} void RestoreWindow(){Show();WindowState=FormWindowState.Normal;Activate();} void ClosingHandler(object? s,FormClosingEventArgs e){if(!closing&&e.CloseReason==CloseReason.UserClosing){e.Cancel=true;HideToTray();}} void ExitApp(){closing=true;tray.Visible=false;try{if(service is{HasExited:false})service.Kill(true);}catch{} service?.Dispose();Application.Exit();}
 bool StartupOn(){using var k=Registry.CurrentUser.OpenSubKey(RunKey);return k?.GetValue(AppName)!=null;} void SetStartup(bool on){using var k=Registry.CurrentUser.CreateSubKey(RunKey);if(on)k.SetValue(AppName,$"\"{Application.ExecutablePath}\"");else k.DeleteValue(AppName,false);}
 static Icon MakeIcon(){using var b=new Bitmap(64,64);using(var g=Graphics.FromImage(b)){g.SmoothingMode=SmoothingMode.AntiAlias;using var br=new LinearGradientBrush(new Rectangle(5,5,54,54),Color.FromArgb(80,100,255),Color.FromArgb(155,75,255),45);g.FillEllipse(br,5,5,54,54);using var f=new Font("Segoe UI",34,FontStyle.Bold);g.DrawString("D",f,Brushes.White,8,4);using var pn=new Pen(Color.White,3);g.DrawRectangle(pn,41,37,14,23);g.DrawEllipse(Brushes.White,46,55,3,3);}return Icon.FromHandle(b.GetHicon());}
}